     9|  Platform,
    10|  Image,
    11|  ScrollView,
    12|} from 'react-native';
    13|import { useSafeAreaInsets } from 'react-native-safe-area-context';
    14|import { useRouter } from 'expo-router';
    15|import { Search, Wind, X, ChevronDown, Check, Plus, ArrowUpDown, Mountain, Trophy } from 'lucide-react-native';
    16|import Colors from '@/constants/colors';
    17|import { MountainCategory } from '@/constants/mountains';
    18|import { useSummits } from '@/contexts/SummitContext';
    19|import { useAllMountains } from '@/hooks/useAllMountains';
    20|import MountainCard from '@/components/MountainCard';
    21|
    22|const categories: Array<{ key: MountainCategory | 'all'; label: string }> = [
    23|  { key: 'all', label: 'All Peaks' },
    24|  { key: '7summits', label: '7 Summits' },
    25|  { key: '8000m', label: '8000m' },
    26|  { key: '14ers', label: '14ers' },
    27|  { key: 'alps', label: 'Alps' },
    28|  { key: 'andes', label: 'Andes' },
    29|  { key: 'himalaya', label: 'Himalaya' },
    30|  { key: 'custom', label: 'My Peaks' },
    31|];
    32|
    33|type SortOption = 'name' | 'elevation_desc' | 'elevation_asc';
    34|
    35|export default function MountainsScreen() {
    36|  const insets = useSafeAreaInsets();
    37|  const router = useRouter();
    38|  const { isSummited, getSummit, getSummitCount } = useSummits();
    39|  const allMountains = useAllMountains();
    40|  const [search, setSearch] = useState('');
    41|  const [selectedCategory, setSelectedCategory] = useState<MountainCategory | 'all'>('all');
    42|  const [sortBy, setSortBy] = useState<SortOption>('elevation_desc');
    43|  const [showSort, setShowSort] = useState(false);
    44|  const [useFeet, setUseFeet] = useState(false);
    45|  const [summitedOnly, setSummitedOnly] = useState<boolean>(false);
    46|
    47|  const filteredMountains = useMemo(() => {
    48|    let filtered = allMountains;
    49|
    50|    if (selectedCategory !== 'all') {
    51|      filtered = filtered.filter((m) => m.category === selectedCategory);
    52|    }
    53|
    54|    if (summitedOnly) {
    55|      filtered = filtered.filter((m) => isSummited(m.id));
    56|    }
    57|
    58|    if (search.trim()) {
    59|      const q = search.toLowerCase().trim();
    60|      filtered = filtered.filter(
    61|        (m) =>
    62|          m.name.toLowerCase().includes(q) ||
    63|          m.country.toLowerCase().includes(q) ||
    64|          m.range.toLowerCase().includes(q)
    65|      );
    66|    }
    67|
    68|    switch (sortBy) {
    69|      case 'name':
    70|        return [...filtered].sort((a, b) => a.name.localeCompare(b.name));
    71|      case 'elevation_asc':
    72|        return [...filtered].sort((a, b) => a.elevation - b.elevation);
    73|      case 'elevation_desc':
    74|      default:
    75|        return [...filtered].sort((a, b) => b.elevation - a.elevation);
    76|    }
    77|  }, [search, selectedCategory, sortBy, allMountains, summitedOnly, isSummited]);
    78|
    79|  const handleMountainPress = useCallback((id: string) => {
    80|    router.push(`/mountain/${id}` as any);
    81|  }, [router]);
    82|
    83|  const handleO2Press = useCallback(() => {
    84|    router.push('/o2-equivalent' as any);
    85|  }, [router]);
    86|
    87|  const handleAddMountain = useCallback(() => {
    88|    router.push('/add-mountain' as any);
    89|  }, [router]);
    90|
